const headers = $input.first().headers;
const expectedSecret = $env.WEBHOOK_SECRET;

// TODO Phase 3: enable HMAC validation
// if (!expectedSecret) return $input.all();
// if (headers['x-webhook-signature'] !== expectedSecret) throw new Error('Unauthorized');

return $input.all();

// INPUT: { question: string } from webhook body
// OUTPUT: cleaned question string

const question = $input.first().json.question || $input.first().json.body?.question || '';
return [{ json: { question: question.trim() } }];

// Build LLM prompt with retrieved context
// Falls back to "not found" if no relevant docs

const question = $('Parse Question').first().json.question;
const docs = $input.all().map(item => item.json).filter(d => d.content);

if (docs.length === 0) {
  return [{
    json: {
      question: question,
      answer: 'Diese Information liegt mir nicht vor. Bitte wende dich an hr@novawork.de.',
      sources: [],
      context_used: false
    }
  }];
}

const context = docs.map((d, i) => `[${i + 1}] ${d.metadata?.filename || 'Doc ' + (i + 1)}:
${d.content.slice(0, 1000)}`).join('\n\n');

const systemPrompt = `Du bist der NovaWork HR Assistant. Antwortest du NUR mit faktischen Informationen aus den bereitgestellten Dokumenten. Zitiere die Quelle [Dokumentname]. Wenn eine Frage nicht beantwortet werden kann: "Diese Information liegt mir nicht vor. Bitte wende dich an hr@novawork.de."`;

return [{
  json: {
    question: question,
    context: context,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `Frage: ${question}\n\nRelevante Dokumente:\n${context}\n\nAntwort:` }
    ]
  }
}];

// Format LLM response + metadata for webhook response
// Handles both OpenAI-compatible and Anthropic response formats

const llmResult = $input.first().json;
const answer = llmResult.choices?.[0]?.message?.content || llmResult.content?.[0]?.text || '';
const question = $('Parse Question').first().json.question;
const contextUsed = $('Build Prompt with Context').first().json.context_used !== false;

return [{
  json: {
    question: question,
    answer: answer,
    sources: contextUsed ? $('Supabase Similarity Search').all().map(d => d.json.metadata?.filename).filter(Boolean) : [],
    timestamp: new Date().toISOString()
  }
}];
